using System;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using TasiaCraft;
public static class CropMoveTest {
 static string root,log;static int passed;static LivePreview preview;static readonly JavaScriptSerializer json=new JavaScriptSerializer();
 static void Require(bool ok,string label){if(!ok)throw new Exception(label);passed++;File.AppendAllText(log,"PASS "+label+Environment.NewLine);}
 static void Near(double actual,double expected,string label){Require(Math.Abs(actual-expected)<.000001,label+" actual "+actual+" expected "+expected);}
 static void Same(Point a,Point b,string label){Require((a-b).Length<.000001,label+" actual "+a+" expected "+b);}
 static void Reject(Action action,string label){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}Require(rejected,label);}
 static void Fixture(string path,int w,int h,bool split){using(var b=new System.Drawing.Bitmap(w,h)){using(var g=System.Drawing.Graphics.FromImage(b)){g.Clear(split?System.Drawing.Color.Red:System.Drawing.Color.Lime);if(split)g.FillRectangle(System.Drawing.Brushes.Blue,w/2,0,w/2,h);}b.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
 static Border Layer(){return preview.Stage.Children.OfType<Border>().Last();}
 static Point Corner(bool right,bool bottom){preview.UpdateLayout();var box=Layer();var rect=box.Clip.Bounds;return box.TransformToAncestor(preview.Stage).Transform(new Point(right?rect.Right:rect.Left,bottom?rect.Bottom:rect.Top));}
 static Project Setup(Media media,Media green,Clip c,int w,int h){var p=new Project{Width=w,Height=h};p.Media.Add(green);p.Media.Add(media);p.Clips.Add(new Clip{MediaId=green.Id,Duration=1});c.MediaId=media.Id;c.Duration=1;c.Track=1;p.Clips.Add(c);preview.SetProject(p);preview.Seek(.2);preview.UpdateLayout();return p;}
 static byte[] PreviewPixels(int w,int h){preview.UpdateLayout();var bitmap=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);bitmap.Render(preview.Stage);var pixels=new byte[w*h*4];bitmap.CopyPixels(pixels,w*4,0);return pixels;}
 static byte[] ExportPixels(Project p,string name){string video=Path.Combine(root,name+".mp4"),png=Path.Combine(root,name+".png");Engine.Render(p,video,null);Engine.Run("ffmpeg","-y -v error -ss 0.2 -i "+Engine.Quote(video)+" -frames:v 1 -threads 1 "+Engine.Quote(png));using(var b=new System.Drawing.Bitmap(png)){Require(b.Width==p.Width&&b.Height==p.Height,name+" export dimensions");var pixels=new byte[b.Width*b.Height*4];for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){var c=b.GetPixel(x,y);int n=(y*b.Width+x)*4;pixels[n]=c.B;pixels[n+1]=c.G;pixels[n+2]=c.R;pixels[n+3]=c.A;}return pixels;}}
 static void Color(byte[] pixels,int w,int x,int y,int channel,string label){int n=(y*w+x)*4;Require(pixels[n+channel]>180&&pixels[n+(channel+1)%3]<75&&pixels[n+(channel+2)%3]<75,label);}
 static void ReferencePixels(byte[] p,string label){Color(p,320,20,90,1,label+" left outside aperture green");Color(p,320,50,90,2,label+" left aperture red");Color(p,320,170,90,2,label+" source split moved to180");Color(p,320,200,90,0,label+" right aperture blue");Color(p,320,290,90,1,label+" right outside aperture green");}
 [STAThread]public static void Main(string[] args){root=args[0];Directory.CreateDirectory(root);log=Path.Combine(root,"results.txt");File.WriteAllText(log,"");var app=new Application();preview=new LivePreview();var window=new Window{Width=1000,Height=800,Content=preview,Title="TatsiaCraft isolated crop source movement"};window.Loaded+=async(s,e)=>{try{
  string split=Path.Combine(root,"split.png"),background=Path.Combine(root,"green.png");Fixture(split,320,180,true);Fixture(background,320,180,false);var media=Engine.Probe(split);var green=Engine.Probe(background);
  var c=new Clip{NativeSize=true,CropLeft=.125,CropRight=.125};var p=Setup(media,green,c,320,180);Point first=Corner(false,false),last=Corner(true,true),down=new Point(100,90);string original=json.Serialize(c);var op=new CanvasCropMoveOperation(c,320,180,down);var result=op.Evaluate(new Point(120,100));Require(json.Serialize(c)==original,"evaluate does not mutate clip");Near(result.X,20,"observed source X after20px drag");Near(result.Y,0,"uncropped vertical axis does not move");Near(result.CropLeft,.0625,"observed crop left after20px drag");Near(result.CropRight,.1875,"observed crop right after20px drag");result.ApplyTo(c);preview.Refresh();await Task.Delay(40);Same(Corner(false,false),first,"reference top-left aperture fixed");Same(Corner(true,true),last,"reference bottom-right aperture fixed");ReferencePixels(PreviewPixels(320,180),"reference preview");ReferencePixels(ExportPixels(p,"reference-move"),"reference export");
  string saved=Path.Combine(root,"moved.tasia");Engine.Save(p,saved);var reopened=Engine.Load(saved);Near(reopened.Clips[1].X,20,"save/reopen X");Near(reopened.Clips[1].CropLeft,.0625,"save/reopen left crop");Near(reopened.Clips[1].CropRight,.1875,"save/reopen right crop");ReferencePixels(ExportPixels(reopened,"reopened-move"),"reopened export");var clamped=op.Evaluate(new Point(900,900));Near(clamped.X,40,"observed source boundary X clamp");Near(clamped.CropLeft,0,"observed left crop clamp");Near(clamped.CropRight,.25,"observed right crop clamp");clamped.ApplyTo(c);preview.Refresh();Same(Corner(false,false),first,"clamped reference aperture top-left fixed");Same(Corner(true,true),last,"clamped reference aperture bottom-right fixed");
  foreach(double angle in new[]{0.0,90.0,33.0})foreach(double scale in new[]{.4,1.5})foreach(bool native in new[]{false,true}){
   string label="robustness angle "+angle+" scale "+scale+" native "+native;c=new Clip{NativeSize=native,Scale=scale,Rotation=angle,X=13,Y=-7,CropLeft=.2,CropTop=.15,CropRight=.1,CropBottom=.2};Setup(media,green,c,800,600);Point tl=Corner(false,false),br=Corner(true,true);var box=Layer();Point sourceOrigin=box.TransformToAncestor(preview.Stage).Transform(new Point(0,0));Point sourceDelta=box.TransformToAncestor(preview.Stage).Transform(new Point(box.Width*.05,box.Height*.05));Vector delta=sourceDelta-sourceOrigin;down=new Point(400,300);op=new CanvasCropMoveOperation(c,box.Width,box.Height,down);original=json.Serialize(c);var unchanged=op.Evaluate(down);Near(unchanged.X,13,label+" no X jump");Near(unchanged.Y,-7,label+" no Y jump");result=op.Evaluate(down+delta);Require(json.Serialize(c)==original,label+" evaluate preserves source clip");result.ApplyTo(c);Near(c.CropLeft,.15,label+" local left crop shift");Near(c.CropTop,.1,label+" local top crop shift");Near(c.CropRight,.15,label+" local right crop shift");Near(c.CropBottom,.25,label+" local bottom crop shift");Near(c.Scale,scale,label+" scale unchanged");Near(c.Rotation,angle,label+" rotation unchanged");preview.Refresh();Same(Corner(false,false),tl,label+" actual top-left aperture fixed");Same(Corner(true,true),br,label+" actual bottom-right aperture fixed");result=op.Evaluate(down+delta*1000);result.ApplyTo(c);preview.Refresh();Near(c.CropLeft,0,label+" local left bound clamp");Near(c.CropTop,0,label+" local top bound clamp");Same(Corner(false,false),tl,label+" clamped actual top-left fixed");Same(Corner(true,true),br,label+" clamped actual bottom-right fixed");result=op.Evaluate(down-delta*1000);result.ApplyTo(c);preview.Refresh();Near(c.CropRight,0,label+" local right bound clamp");Near(c.CropBottom,0,label+" local bottom bound clamp");Same(Corner(false,false),tl,label+" reverse-clamped top-left fixed");Same(Corner(true,true),br,label+" reverse-clamped bottom-right fixed");
  }
  c=new Clip{NativeSize=true,CropLeft=.5,Rotation=90};p=Setup(media,green,c,800,600);first=Corner(false,false);new CanvasCropMoveOperation(c,320,180,new Point(400,300)).Evaluate(new Point(400,340)).ApplyTo(c);preview.Refresh();Same(Corner(false,false),first,"rotated independent source movement aperture fixed");await Task.Delay(30);foreach(var pixels in new[]{PreviewPixels(800,600),ExportPixels(p,"rotated-move")}){Color(pixels,800,400,320,2,"rotated movement reveals formerly cropped red");Color(pixels,800,400,400,0,"rotated movement retained blue");Color(pixels,800,400,280,1,"rotated movement fixed aperture upper green");}
  foreach(double angle in new[]{0.0,33.0,90.0}){c=new Clip{NativeSize=true,CropLeft=.3,CropTop=.2,CropRight=.2,CropBottom=.2,X=32767,Y=32767,Rotation=angle};Setup(media,green,c,800,600);first=Corner(false,false);last=Corner(true,true);new CanvasCropMoveOperation(c,320,180,new Point()).Evaluate(new Point(10000,10000)).ApplyTo(c);Require(Math.Abs(c.X)<=32768&&Math.Abs(c.Y)<=32768,"position bound angle "+angle);preview.Refresh();Same(Corner(false,false),first,"position bound retains top-left angle "+angle);Same(Corner(true,true),last,"position bound retains bottom-right angle "+angle);}
  Reject(()=>new CanvasCropMoveOperation(null,320,180,new Point()),"null clip rejected");Reject(()=>new CanvasCropMoveOperation(new Clip(),0,180,new Point()),"zero dimension rejected");Reject(()=>new CanvasCropMoveOperation(new Clip(),320,double.NaN,new Point()),"NaN dimension rejected");Reject(()=>new CanvasCropMoveOperation(new Clip{Scale=double.PositiveInfinity},320,180,new Point()),"infinite scale rejected");Reject(()=>new CanvasCropMoveOperation(new Clip{CropLeft=.8,CropRight=.3},320,180,new Point()),"overcrop rejected");Reject(()=>new CanvasCropMoveOperation(new Clip{CropTop=double.NaN},320,180,new Point()),"NaN crop rejected");Reject(()=>new CanvasCropMoveOperation(new Clip(),320,180,new Point(double.PositiveInfinity,0)),"infinite pointer down rejected");Reject(()=>op.Evaluate(new Point(double.NaN,0)),"NaN pointer evaluation rejected");Reject(()=>result.ApplyTo(null),"null apply rejected");
  preview.Dispose();File.AppendAllText(log,"PASS total "+passed+Environment.NewLine);app.Shutdown(0);
 }catch(Exception ex){File.AppendAllText(log,"FAIL "+ex+Environment.NewLine);preview.Dispose();app.Shutdown(1);}};app.Run(window);}
}


